    UPDATE "member_attendance"
       SET "Num_of_Pieces" = "Num_of_Pieces" + para_Performance_ID
     WHERE "Num_of_Pieces" < var1;

    DELETE FROM "performance"
     WHERE "Attendance" = para_Attendance
       AND "integer" LIKE var2;

