        JOIN "member_attendance" ma
          ON ma."Num_of_Pieces" = p."Attendance"
       WHERE p."Attendance" > para_Attendance
    ) THEN
      UPDATE "member_attendance" AS ma
         SET "Performance_ID" = p."integer"
        FROM "performance" AS p
       WHERE p."Attendance" > para_Attendance
         AND ma."Num_of_Pieces" = p."Attendance";
